from ..exceptions import InvalidStatus


class Status(object):
    __slots__ = ['_component', '_name', '_value']

    def __init__(self, component, name, value):
        """
        :param component: runtime distName of status component
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param name: name of status, i.e. 'availabilityStatus'
        :type name: str
        :param value: value of status, i.e. 'Offline';
                      use None when creating status without value (i.e. 'Online' after CNI-61110)
        :type value: str or None
        """
        self._component = component
        self._name = name
        self._value = value

    def __str__(self):
        return f"Component: '{self._component}', Name: '{self._name}', Value: '{self._value}'"

    def __repr__(self):
        return f"{self.__class__.__name__}({self._component}, {self._name}, {self._value})"

    @property
    def component(self):
        """
        :return: runtime distName of status component
        :rtype: str
        """
        return self._component

    @property
    def name(self):
        """
        :return: name of status, i.e. 'availabilityStatus'
        :rtype: str
        """
        return self._name

    @property
    def value(self):
        """
        :return: value of status, i.e. 'Offline';
                 None when status has no value (i.e. 'Online' after CNI-61110)
        :rtype: str or None
        """
        return self._value

    def has_only_different_value_from(self, other):
        """
        Determines whether two statuses have all attributes equal EXCEPT of their values.

        :param other: status which will be used during comparison
        :type other: Status
        :return: True when statuses have unequal values but all other attributes equal, False otherwise
        :rtype: bool
        :raises InvalidStatus: when other status is missing any attribute used during comparison
        """
        self._check_for_missing_attributes(other)
        return self._component == other.component and self._name == other.name and self._value != other.value

    def __eq__(self, other):
        """
        Determines whether two statuses have all attributes equal.

        :param other: status which will be used during comparison
        :type other: Status
        :return: True when statuses have all attributes equal, False otherwise
        :rtype: bool
        :raises InvalidStatus: when other status is missing any attribute used during comparison
        """
        self._check_for_missing_attributes(other)
        return self._component == other.component and self._name == other.name and self._value == other.value

    def __hash__(self):
        return hash((self._component, self._name, self._value))

    @staticmethod
    def _check_for_missing_attributes(status):
        for attribute in ['component', 'name', 'value']:
            if not hasattr(status, attribute):
                raise InvalidStatus("Status without {} attribute cannot be used in comparison".format(attribute))
